const fs = require("fs");
// Lives in scripts/; build from the book root so "chapters/" and the manuscript land where they always did.
process.chdir(require("path").join(__dirname, ".."));
const {
  Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType,
  TableOfContents, PageBreak,
} = require("docx");

const PAGE = { size: { width: 12240, height: 15840 } }; // US Letter

const HEADLINE_FONT = "Amazon Ember";
const HEADLINE_SIZE = 36; // half-points => 18pt
const HEADLINE_COLOR = "0000FF";

function heading(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_1,
    outlineLevel: 0,
    alignment: AlignmentType.CENTER,
    spacing: { after: 300 },
    children: [new TextRun({
      text, bold: true,
      font: HEADLINE_FONT, size: HEADLINE_SIZE, color: HEADLINE_COLOR,
    })],
  });
}

function body(text) {
  return new Paragraph({
    spacing: { after: 200 },
    children: [new TextRun({ text })],
  });
}

function subhead(text) {
  return new Paragraph({
    heading: HeadingLevel.HEADING_2,
    outlineLevel: 1,
    alignment: AlignmentType.CENTER,
    spacing: { before: 300, after: 150 },
    keepNext: true,
    children: [new TextRun({
      text, bold: true,
      font: HEADLINE_FONT, size: HEADLINE_SIZE, color: HEADLINE_COLOR,
    })],
  });
}

function grade(label, comment) {
  return new Paragraph({
    spacing: { after: 200 },
    children: [
      new TextRun({ text: label + ". ", bold: true }),
      new TextRun({ text: comment }),
    ],
  });
}

function italic(text) {
  return new Paragraph({
    spacing: { after: 200 },
    children: [new TextRun({ text, italics: true })],
  });
}

function verdict(text) {
  return [
    new Paragraph({
      spacing: { after: 100 },
      children: [new TextRun({ text: "Dolphin verdict:", bold: true })],
    }),
    new Paragraph({
      spacing: { after: 200 },
      children: [new TextRun({ text, italics: true })],
    }),
  ];
}

function makeDoc(children) {
  return new Document({
    sections: [{ properties: { page: PAGE }, children }],
  });
}

async function save(name, children) {
  const doc = makeDoc(children);
  const buf = await Packer.toBuffer(doc);
  fs.writeFileSync(name, buf);
  console.log("wrote", name);
}

